edits.before:
// Use input's parent if in form-adorn
if (!positionElement && this._isInput && !this._isInline) {
  const parent = this._element.closest<HTMLElement>('.form-adorn')
  if (parent) {
    positionElement = parent
  }
}

edits.after:
// Use input's parent if in form-adorn
if (!positionElement && this._isInput && !this._isInline) {
  const parent = this._element.closest<HTMLElement>('.form-adorn')
  if (parent) {
    positionElement = parent
  } else {
    // Use the parent element of the input for positioning to avoid the input being modified
    positionElement = this._element.parentElement as HTMLElement || this._element
  }
}
